import {newCanvasSnapshot} from './new-content-labels.js';
import {t, useI18n, getLanguage} from './i18n.js';
import {useEffect,useRef,useState} from 'react';
import {captureThumbnail} from './thumbnail-capture.js';
import {BoardCardMenu} from './board-card-menu.js';
import {Plus,Search,Layers3,X} from 'lucide-react';
import type {BoardDocument} from '../core/types.js';
export type BoardSummary=Omit<BoardDocument,'snapshot'>&{pageCount:number;shapeCount:number;thumbnail?:{version:number;capturedAt:string}};
export function BoardManager({items,open,refresh,controls,onShare,onOpenWindow}:{items:BoardSummary[];open:(id:string)=>void;refresh:()=>Promise<void>;controls:React.ReactNode;onShare?:(item:BoardSummary)=>void;onOpenWindow?:(id:string)=>void}){
  useI18n();
 const [query,setQuery]=useState(''),[dialog,setDialog]=useState<{action:'create'|'rename'|'duplicate'|'delete';item?:BoardSummary}>(),[title,setTitle]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);const pending=useRef(false);
 const previewPending=useRef(false),previewFailures=useRef(new Map<string,number>());
 useEffect(()=>{
  if(previewPending.current)return;
  const item=items.find(board=>board.thumbnail?.version!==board.version&&Date.now()-(previewFailures.current.get(board.id+':'+board.version)??0)>30000);
  if(!item)return;previewPending.current=true;let disposed=false;
  void captureThumbnail(item.id,false).then(async(saved)=>{if(!saved)previewFailures.current.set(item.id+':'+item.version,Date.now());if(saved&&!disposed)await refresh();}).catch(()=>{previewFailures.current.set(item.id+':'+item.version,Date.now());}).finally(()=>{previewPending.current=false;});
  return()=>{disposed=true;};
 },[items,refresh]);
 const show=(action:'create'|'rename'|'duplicate'|'delete',item?:BoardSummary)=>{setTitle(action==='create'?t("新的白板"):action==='duplicate'?(item!.title+t(" 副本")).slice(0,120):item!.title);setError('');setDialog({action,...(item?{item}:{})});};
 const exportBoard=(item:BoardSummary)=>{const anchor=document.createElement('a');anchor.href='/api/boards/'+encodeURIComponent(item.id)+'/export';anchor.download=(item.title.replace(/[<>:"/\\|?*\x00-\x1f]/gu,'_').replace(/[. ]+$/gu,'').trim()||t("MOKI白板"))+'.moki';document.body.appendChild(anchor);anchor.click();anchor.remove();};
 const close=()=>{if(!pending.current)setDialog(undefined);};
 const submit=async()=>{if(!dialog||pending.current)return;pending.current=true;setBusy(true);setError('');try{
  if(dialog.action!=='delete'&&!title.trim())throw new Error(t("请输入白板名称"));
  const item=dialog.item,action=dialog.action;
  const path=action==='create'?'/api/boards':'/api/boards/'+item!.id+(action==='duplicate'?'/duplicate':action==='delete'?'?expectedVersion='+item!.version:'');
  const response=await fetch(path,{method:action==='delete'?'DELETE':action==='rename'?'PATCH':'POST',headers:action==='delete'?{}:{'content-type':'application/json'},...(action==='delete'?{}:{body:JSON.stringify({title:title.trim(),expectedVersion:item?.version,...(action==='create'?{snapshot:newCanvasSnapshot()}:{})})})});
  const body=response.status===204?undefined:await response.json();if(!response.ok)throw new Error(response.status===409?t("白板已更新，请关闭弹窗后重新操作，以免覆盖其他编辑。"):body.error??t("操作失败"));
  setDialog(undefined);await refresh();if(action==='create')open(body.id);
 }catch(e){setError(e instanceof Error?e.message:String(e));await refresh();}finally{pending.current=false;setBusy(false);}};
 const filtered=items.filter(item=>item.title.toLowerCase().includes(query.trim().toLowerCase()));
 return <main className="manager-shell"><header className="manager-header"><div className="manager-brand"><img className="manager-brand-icon" src="/moki-whiteboard-icon.png" alt={t("MOKI 白板图标")} width={56} height={56}/><div><p>MOKI CANVAS</p><h1>{t("MOKI 白板")}</h1><span>{t("让想法自由生长，也让 Agent 加入创作。")}</span></div></div><div className="manager-actions">{controls}<button className="manager-primary" onClick={()=>show('create')}><Plus size={18}/>{t("新建白板")}</button></div></header><section className="manager-content"><div className="manager-section-title"><div><h2>{t("我的白板")}</h2><p>{items.length} {t("张白板 · 按最近编辑排序")}</p></div><label className="manager-search"><Search size={17}/><input aria-label={t("搜索白板")} value={query} onChange={e=>setQuery(e.target.value)} placeholder={t("搜索白板")}/></label></div><div className="board-scroll" role="region" aria-label={t("白板卡片列表")} tabIndex={0}><div className="board-grid"><button className="board-card new-board-card" onClick={()=>show('create')}><Plus size={32}/><strong>{t("新建白板")}</strong><span>{t("开启一张无限画布")}</span></button>{filtered.map(item=><article className="board-card" key={item.id}><button className="board-open" aria-label={t("编辑白板 ")+item.title} onClick={()=>open(item.id)}><div className="board-preview">{item.thumbnail?<img alt={item.title+t("上次编辑截图")} src={'/api/boards/'+item.id+'/thumbnail?v='+item.thumbnail.version+'&t='+encodeURIComponent(item.thumbnail.capturedAt)}/>:<><Layers3 size={30}/><span>{t("打开白板后生成编辑截图")}</span></>}</div><h3>{item.title}</h3><p>{item.pageCount} {t("个页面 ·")}{item.shapeCount} {t("项内容")}</p></button><div className="board-card-footer"><small>{new Date(item.updatedAt).toLocaleString(getLanguage())}{item.thumbnail&&item.thumbnail.version!==item.version?t(" · 截图待更新"):''}</small><BoardCardMenu title={item.title} canOpenWindow={Boolean(onOpenWindow)} onAction={action=>{if(action==='open-window')onOpenWindow?.(item.id);else if(action==='export')exportBoard(item);else if(action==='share')onShare?.(item);else show(action,item);}}/></div></article>)}</div>{query&&filtered.length===0?<p className="manager-empty">{t("没有找到匹配的白板")}</p>:null}</div></section><footer className="manager-footer">Power by JKZeng</footer>
 {dialog?<div className="native-modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close();}}><form className="native-mcp-modal manager-dialog" role="dialog" aria-modal="true" aria-label={{create:t("新建白板"),rename:t("重命名白板"),duplicate:t("复制白板"),delete:t("删除白板")}[dialog.action]} onKeyDown={e=>{if(e.key==='Escape')close();}} onSubmit={e=>{e.preventDefault();void submit();}}><button type="button" className="native-modal-close" aria-label={t("关闭")} disabled={busy} onClick={close}><X size={18}/></button><h2>{{create:t("新建白板"),rename:t("重命名白板"),duplicate:t("复制白板"),delete:t("删除白板")}[dialog.action]}</h2>{dialog.action==='delete'?<p>{t("确认删除“")}{dialog.item!.title}{t("”？白板内容将被删除，此操作无法撤回。")}</p>:<label>{t("白板名称")}<input autoFocus aria-label={t("白板名称")} maxLength={120} value={title} disabled={busy} onChange={e=>setTitle(e.target.value)}/></label>}{error?<p role="alert" className="manager-dialog-error">{error}</p>:null}<div className="manager-dialog-actions"><button type="button" onClick={close} disabled={busy}>{t("取消")}</button><button type="submit" className="manager-primary" disabled={busy||(dialog.action!=='delete'&&!title.trim())}>{busy?t("处理中…"):dialog.action==='delete'?t("确认删除"):dialog.action==='create'?t("创建并编辑"):t("保存")}</button></div></form></div>:null}</main>;
}
